import sys
import math

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        ops = []

        if n == 3:
            ops.append((3, 2))
            ops.append((3, 2))
        else:
            cur = n
            while cur > 1:
                target = math.ceil(math.sqrt(cur))
                if target == 1:
                    target = 2
                if target < 2:
                    target = 2

                if cur == target:
                    break

                if target == 1:
                    ops.append((cur, 2))
                    cur = 2
                elif cur == target:
                    break
                else:
                    if cur == target:
                        break

                    if target == 2:
                        ops.append((cur, 2))
                        cur = 2
                    else:
                        ops.append((cur, target))
                        cur = target

            for i in range(2, n + 1):
                if i != cur:
                    ops.append((i, cur))

            while cur > 2:
                ops.append((cur, 2))
                cur = math.ceil(cur / 2)

            if cur == 2:
                pass
            else:
                ops.append((cur, 2))

        results.append(str(len(ops)))
        for x, y in ops:
            results.append(f"{x} {y}")

    print('\n'.join(results))

if __name__ == '__main__':
    solve()
